/** The signed-in user's locale. */
public class RespondWithLocale {
    public void respond(LocaleRepository locales, HttpServletRequest request, ObjectResponse<LocaleResponse> response) {
        response.send(new LocaleResponse(locales.localeOf(Audit.user(request))));
    }
}
package net.officefloor.hq.app.locale;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.setting.InvalidSettingException;
import net.officefloor.plugin.variable.Val;

/** The signed-in user's locale is saved; it moves no figures and writes no audit line. */
public class SaveLocale {
    public void save(@Val LocaleInput input, LocaleRepository locales, HttpServletRequest request)
            throws InvalidSettingException {
        String user = Audit.user(request);
        if (user.isBlank()) throw new InvalidSettingException("Sign in to choose a locale");
        locales.save(user, input.locale());
    }
}
package net.officefloor.hq.app.locale;

import java.util.Set;
import net.officefloor.hq.app.setting.InvalidSettingException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateLocale {

    private static final Set<String> LOCALES = Set.of("en", "de");

    public void validate(@RequestBody LocaleRequest request, Out<LocaleInput> body) throws InvalidSettingException {
        String locale = request == null || request.locale() == null ? "" : request.locale().trim();
        if (!LOCALES.contains(locale)) throw new InvalidSettingException("A locale is en or de");
        body.set(new LocaleInput(locale));
    }
}
