import { useEffect, useRef, useState } from 'react';
import type { RefObject } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useOnce } from '../../query/useOnce';
import { postOwnJson } from '../../api/http';
import { SheetBody } from '../../slots/defs/sheetBody';
import { LOCALES, localeKey, showFigure, useLocale } from './locale';
import type { Locale } from './locale';

// What a text node held before it was shown in the locale, and what it shows now; so a node React
// has since rewritten is told from one still showing our text, and a switch back can restore it.
const shownAs = new WeakMap<Text, { original: string; shown: string }>();

function localize(node: Text, locale: Locale) {
  const parent = node.parentElement;
  if (!parent || parent.closest('textarea, script, style')) return;
  const seen = shownAs.get(node);
  const current = node.nodeValue ?? '';
  const original = seen && seen.shown === current ? seen.original : current;
  const shown = showFigure(original, locale);
  if (shown !== current) node.nodeValue = shown;
  if (shown === original) shownAs.delete(node);
  else shownAs.set(node, { original, shown });
}

function localizeAll(root: Node, locale: Locale) {
  if (root.nodeType === Node.TEXT_NODE) {
    localize(root as Text, locale);
    return;
  }
  const walk = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  for (let n = walk.nextNode(); n; n = walk.nextNode()) localize(n as Text, locale);
}

/**
 * Shows every figure in the sheet body in `locale`: any text whose whole is a number with two
 * decimals, wherever a feature renders it. Features keep rendering figures as the server sends them
 * (as typed, a dot before the decimals); this rewrites them on screen only, as they appear.
 */
function useFiguresIn(anchor: RefObject<HTMLElement | null>, locale: Locale) {
  useEffect(() => {
    const root = anchor.current?.closest('[data-testid="sheet-body"]');
    if (!root) return;
    localizeAll(root, locale);
    const observer = new MutationObserver((records) => {
      for (const r of records) {
        if (r.type === 'characterData') localize(r.target as Text, locale);
        else r.addedNodes.forEach((n) => localizeAll(n, locale));
      }
    });
    observer.observe(root, { subtree: true, childList: true, characterData: true });
    return () => observer.disconnect();
  }, [anchor, locale]);
}

// The signed-in user's locale: a choice, the button that saves it, and the locale in force. It is
// the user's own, kept across sheets; it changes nothing on the sheet and writes no audit line.
function UserLocale({ user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const locale = useLocale(user);
  const current: Locale = locale.data ?? 'en';
  const [choice, setChoice] = useState<Locale | ''>('');
  const [error, setError] = useState('');
  const anchor = useRef<HTMLFormElement>(null);
  useFiguresIn(anchor, current);

  const once = useOnce();
  const save = useMutation({
    mutationFn: (chosen: Locale) => postOwnJson<{ locale: Locale }>('/api/locale', { locale: chosen }, user),
    onSuccess: (saved) => queryClient.setQueryData(localeKey(user), saved.locale),
    onError: () => setError('That locale could not be saved.'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const chosen = choice || current;
    once((done) => save.mutate(chosen, { onSettled: done }));
  };

  return (
    <form ref={anchor} onSubmit={submit} data-testid="user-locale-form">
      <label>
        Locale{' '}
        <select
          data-testid="user-locale"
          value={choice || current}
          onChange={(e) => {
            setChoice(e.target.value as Locale);
            setError('');
          }}
        >
          {LOCALES.map((l) => (
            <option key={l} value={l}>
              {l}
            </option>
          ))}
        </select>
      </label>{' '}
      <button type="submit" data-testid="user-locale-save" disabled={save.isPending}>
        Save locale
      </button>{' '}
      Locale: <strong data-testid="user-locale-current">{locale.data ?? ''}</strong>
      {(error || locale.isError) && (
        <p role="alert" data-testid="user-locale-error">
          {error || 'The locale could not be read.'}
        </p>
      )}
    </form>
  );
}

export const contribution = SheetBody.fill({ order: -95, Component: UserLocale });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

// The locale is per user, not per sheet: it decides how the screen shows that user figures.
export const LOCALES = ['en', 'de'] as const;
export type Locale = (typeof LOCALES)[number];

export const localeKey = (user: string) => ['user', user, 'locale'] as const;

/** The signed-in user's locale: en until they choose another. */
export function useLocale(user: string) {
  return useQuery({
    queryKey: localeKey(user),
    queryFn: async () =>
      (await getJson<{ locale: Locale }>('/api/locale', user)).locale,
  });
}

// A figure as the screen shows it under en: digits, a dot, exactly two decimals.
const FIGURE = /^(\s*)(-?)(\d+)\.(\d{2})(\s*)$/;

/** A figure's text as shown under `locale`; any other text unchanged. Under de, 1234.56 is
 *  1.234,56: a dot every three digits and a comma before the decimals. */
export function showFigure(text: string, locale: Locale): string {
  if (locale !== 'de') return text;
  const m = FIGURE.exec(text);
  if (!m) return text;
  const whole = m[3].replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  return `${m[1]}${m[2]}${whole},${m[4]}${m[5]}`;
}
import type { ComponentType } from 'react';

// The contribution store. It imports NOTHING — that is deliberate: discovery (slots/discover.ts)
// pulls in every feature's contribution file, and those files reach a slot definition, which
// reaches defineSlot, which reaches this file. Keeping the arrows one-way (discover -> features ->
// defs -> Slot -> registry) is what stops the module graph forming a cycle.

export type Registered = {
  slot: string;
  order: number;
  /** Source file — the React key and the deterministic tie-break for equal `order`. */
  from: string;
  Component: ComponentType<never>;
};

const contributions: Registered[] = [];

/** Called once per contribution at startup, by slots/discover.ts. */
export function register(entry: Registered): void {
  contributions.push(entry);
}

export function forSlot(id: string): Registered[] {
  return contributions
    .filter((c) => c.slot === id)
    .sort((a, b) => a.order - b.order || a.from.localeCompare(b.from));
}
import { Fragment, createElement } from 'react';
import type { ComponentType, ReactElement } from 'react';
import { forSlot } from './registry';

// ── Slots: regions of the UI that features fill ───────────────────────────────────────────────
// A SLOT is a region of the UI that features fill. Whatever renders a region does not list what
// goes in it; a contribution to a region (a panel, a table column, a row action, a toolbar
// control, a nav link) is a separate file, registered by discovery (slots/discover.ts).
//
//   1. declare a region  ->  slots/defs/projectDetail.ts
//        export const ProjectDetail = defineSlot<{ projectId: number }>('project.detail');
//   2. render it         ->  <ProjectDetail.Slot projectId={id} />
//   3. fill it           ->  features/projects/notes.slot.tsx
//        export const contribution = ProjectDetail.fill({ order: 30, Component: ProjectNotes });
//
// This file, slots/registry.ts and slots/discover.ts implement that mechanism; a region is
// declared by a file under slots/defs/.

export type Contribution<Ctx> = {
  /** Lower renders first; equal orders fall back to file path, so the order is always stable. */
  order?: number;
  Component: ComponentType<Ctx>;
};

export type SlotDef<Ctx extends object> = {
  id: string;
  /** Renders the region. Its props ARE the context handed to every contribution. */
  Slot: (ctx: Ctx) => ReactElement;
  /** A feature wraps its contribution in this, to be typed against the region's context. */
  fill: (contribution: Contribution<Ctx>) => Contribution<Ctx> & { slot: string };
};

export function defineSlot<Ctx extends object = Record<string, never>>(id: string): SlotDef<Ctx> {
  return {
    id,
    // A Fragment, never a wrapper element: a slot must be usable inside <thead>/<tr> (columns and
    // row actions are slots too), where a stray <div> would be invalid markup.
    Slot: (ctx: Ctx) =>
      createElement(
        Fragment,
        null,
        forSlot(id).map((c) =>
          createElement(c.Component as ComponentType<Ctx>, { key: c.from, ...ctx }),
        ),
      ),
    fill: (contribution) => ({ slot: id, ...contribution }),
  };
}
import { useState } from 'react';
import { createFileRoute } from '@tanstack/react-router';
import { SignIn } from '../features/session/SignIn';
import { SheetLoader } from '../features/session/SheetLoader';
import { useSheetId, useUser } from '../features/session/session';
import { SheetBody } from '../slots/defs/sheetBody';

// The one screen. Sign in by name, then load a sheet by id; the loaded sheet's body is the
// sheet.body region, filled by features.
export const Route = createFileRoute('/')({
  component: Home,
});

function Home() {
  const [user] = useUser();
  const [sheetId] = useSheetId();
  // Bumped on every load, so loading the same id again remounts the body for a fresh read.
  const [loads, setLoads] = useState(0);

  if (user === '') {
    return <SignIn />;
  }

  return (
    <>
      <p>
        Signed in as <strong data-testid="current-user">{user}</strong>
      </p>
      <SheetLoader onLoaded={() => setLoads((n) => n + 1)} />
      {sheetId === '' ? (
        <p data-testid="home-empty">Nothing here yet.</p>
      ) : (
        <section data-testid="sheet-body" key={`${sheetId}:${loads}`}>
          <SheetBody.Slot sheetId={sheetId} user={user} />
        </section>
      )}
    </>
  );
}
